<script setup>
// Purpose: Compare original and proposed activity records without mutating the source schedule.
import {computed} from 'vue'
import {controlRoomTime} from '../services/simulatorControlRoomService.js'
const props=defineProps({data:Object,segments:Array,recovery:Object,result:Object,before:Object,savedStatus:String})
const same=(a,b)=>String(a)===String(b)
const member=id=>props.data?.members?.find(m=>same(m.id,id))?.full_name || 'Member '+id
const assignments=computed(()=>props.before?.assignments || props.data?.segment_assignments || [])
const originals=computed(()=>props.before?.segments || props.segments || [])
function names(id,proposed=false){const values=assignments.value.filter(a=>same(a.segment_id,id));return values.map(a=>{const change=proposed?props.recovery?.changes?.find(c=>same(c.segmentId,id)&&same(c.replacedMemberId,a.member_id)&&(c.assignmentId==null||same(c.assignmentId,a.id))):null;return member(change?.replacementMemberId ?? a.member_id)+(a.role_name?' ('+a.role_name+')':'')}).join(', ') || 'No recorded assignment'}
function venues(id){const links=props.before?.links || props.data?.segment_facility_bookings || [];return links.filter(l=>same(l.segment_id,id)).map(l=>{const booking=props.data?.facility_bookings?.find(b=>same(b.id,l.booking_id));return props.data?.facilities?.find(f=>same(f.id,booking?.facility_id))?.name || 'Booking '+l.booking_id+' (details unavailable)'}).join(', ') || 'No linked facility'}
const rows=computed(()=>originals.value.map(original=>{const proposed=props.recovery?.proposedSegments?.find(s=>same(s.id,original.id));const changes=props.recovery?.changes?.filter(c=>same(c.segmentId,original.id)) || [];const venue=props.recovery?.proposedVenues?.[String(original.id)] || changes.find(c=>c.venueName)?.venueName;const differences=[];if(proposed && (Date.parse(proposed.starts_at)!==Date.parse(original.starts_at)||Date.parse(proposed.ends_at)!==Date.parse(original.ends_at)))differences.push('Schedule');if(names(original.id)!==names(original.id,true))differences.push('Member');if(venue&&venue!==venues(original.id))differences.push('Facility');return {original,proposed,venue,differences}}))
const count=computed(()=>rows.value.filter(r=>r.differences.length).length)
</script>
<template>
 <section class="pulse-card p-3 p-lg-4" aria-label="Plan Comparison">
  <div class="d-flex justify-content-between flex-wrap gap-2 mb-2"><h5 class="fw-bold mb-0">Plan Comparison</h5><span v-if="recovery" class="badge bg-light text-dark border">{{ count }} changed activities</span></div>
  <p v-if="!recovery" class="small text-muted" role="status">Select a recovery plan to compare its proposed changes.</p><p v-else class="small text-muted">{{ recovery.title }} &middot; {{ recovery.saved?(savedStatus==='Undone'?'Undone - historical proposal; original schedule restored.':savedStatus==='Applied'?'Applied recovery - original and applied records.':'Saved proposal; not applied.'):'Preview only; no changes applied.' }}</p>
  <div class="table-responsive" tabindex="0" role="region" aria-label="Scrollable plan comparison"><table class="table align-middle comparison-table"><thead><tr><th>Activity</th><th>Original</th><th>Proposed</th><th>Change</th></tr></thead><tbody><tr v-for="row in rows" :key="row.original.id" :class="{'is-changed':recovery&&row.differences.length,quiet:recovery&&!row.differences.length}"><th scope="row">{{ row.original.title }}</th><td><div>{{ controlRoomTime(row.original.starts_at) }}&ndash;{{ controlRoomTime(row.original.ends_at) }}</div><div>{{ names(row.original.id) }}</div><div>{{ venues(row.original.id) }}</div></td><td><template v-if="recovery"><div>{{ controlRoomTime((row.proposed||row.original).starts_at) }}&ndash;{{ controlRoomTime((row.proposed||row.original).ends_at) }}</div><div>{{ names(row.original.id,true) }}</div><div>{{ row.venue || venues(row.original.id) }}</div></template><span v-else>Not selected</span></td><td>{{ recovery?(row.differences.join(', ')||'Unchanged'):'Not selected' }}</td></tr></tbody></table></div>
  <details v-if="result" class="small mt-2"><summary>Disrupted schedule and impact</summary><p class="text-muted">Simulation output; this is not an approved recovery.</p><div v-for="s in result.simulatedSegments" :key="s.id" class="py-1 border-bottom"><strong>{{ s.title }}</strong> &middot; {{ controlRoomTime(s.starts_at) }}&ndash;{{ controlRoomTime(s.ends_at) }}</div><p class="mt-2 mb-0">{{ result.conflictCounts?.total ?? result.newConflicts?.length ?? 0 }} conflicts &middot; {{ result.downstreamRisks?.length ?? 0 }} downstream risks</p></details>
 </section>
</template>
<style scoped>.comparison-table{min-width:680px;font-size:.8rem}.comparison-table td{max-width:23rem}.comparison-table td div+div{margin-top:.35rem;color:var(--pulse-ink-muted)}.is-changed>th{border-left:3px solid var(--pulse-primary)}.is-changed>td,.is-changed>th{background:var(--pulse-primary-light)}.quiet{color:var(--pulse-ink-muted)}.table-responsive:focus-visible{outline:2px solid var(--pulse-primary);outline-offset:3px}summary{cursor:pointer;min-height:32px}</style>
